/**
 * El logo de ApoyaClub para el pie de la portada del dossier (PDF y
 * Word), uno por idioma porque el eslogan va dentro de la imagen
 * (el mismo eslogan que la web en `common.eslogan`).
 *
 * Es el logo nuevo, el de letras blancas con brillo: solo se ve bien
 * sobre fondo oscuro, así que en el dossier va dentro de una franja
 * del azul marino de la marca (#14304f).
 *
 * Va dentro del código, en base64, y no en `public/`: así el dossier no
 * depende de que el servidor encuentre el archivo ni de descargarlo de
 * la propia web. Son PNG con el fondo transparente, de unos 18 KB.
 */
export const ANCHO_LOGO_DOSSIER = 640;
export const ALTO_LOGO_DOSSIER = 157;

const LOGOS: Record<string, string> = {
  es: "data:image/png;base64,",
  en: "data:image/png;base64,",
  pt: "data:image/png;base64,",
};

/** El logo del idioma del dossier, como `data:` URL (PNG). */
export function logoDelDossier(locale: string): string {
  return LOGOS[locale] ?? LOGOS.es;
}
